"use client";

import {
  ExpandableToolbar,
  type ToolbarItem,
} from "@/registry/blocks/expandable-toolbar";
import {
  FileSpreadsheet,
  FileText,
  FileType2,
  Folder,
  MessageCircle,
  TrendingUp,
  User,
  WalletCards,
} from "lucide-react";

const Panel = ({ children }: { children: React.ReactNode }) => (
  <div className="flex w-full flex-col gap-3 pb-1">{children}</div>
);

const ActionButton = ({ children }: { children: React.ReactNode }) => (
  <button
    type="button"
    className="flex h-8 w-full select-none items-center justify-center rounded-lg bg-muted text-xs font-medium text-foreground transition-colors hover:bg-accent active:scale-[0.98]"
  >
    {children}
  </button>
);

const Avatar = ({
  initials,
  className,
}: {
  initials: string;
  className?: string;
}) => (
  <span
    className={`flex size-8 shrink-0 items-center justify-center rounded-full text-[11px] font-medium text-white ${className}`}
  >
    {initials}
  </span>
);

const ListRow = ({ children }: { children: React.ReactNode }) => (
  <div className="flex items-center gap-2.5 rounded-md p-1.5 transition-colors hover:bg-accent">
    {children}
  </div>
);

const UserPanel = () => (
  <Panel>
    <div className="flex items-center gap-2.5">
      <Avatar
        initials="MI"
        className="bg-linear-to-br from-blue-500 to-blue-400"
      />
      <div className="flex flex-col">
        <span className="text-sm font-medium text-foreground">Mihir</span>
        <span className="text-xs text-muted-foreground">@mihirjaiswal</span>
      </div>
    </div>
    <div className="border-t border-border" />
    <div className="flex flex-col gap-1 text-xs text-muted-foreground">
      <div className="flex justify-between">
        <span>Plan</span>
        <span className="font-medium text-foreground">Pro</span>
      </div>
      <div className="flex justify-between">
        <span>Member since</span>
        <span className="font-medium text-foreground">2023</span>
      </div>
    </div>
    <ActionButton>Edit Profile</ActionButton>
  </Panel>
);

const MESSAGES = [
  {
    initials: "SK",
    color: "bg-linear-to-br from-rose-500 to-rose-400",
    name: "Sarah K.",
    text: "Can you review the PR?",
  },
  {
    initials: "JT",
    color: "bg-linear-to-br from-emerald-500 to-emerald-400",
    name: "James T.",
    text: "Deploy is live",
  },
  {
    initials: "AL",
    color: "bg-linear-to-br from-amber-500 to-amber-400",
    name: "Ana L.",
    text: "Meeting moved to 3pm",
  },
];

const MessagesPanel = () => (
  <Panel>
    <p className="text-xs font-medium text-muted-foreground">3 new messages</p>
    <div className="flex flex-col">
      {MESSAGES.map((m) => (
        <ListRow key={m.name}>
          <Avatar initials={m.initials} className={m.color} />
          <div className="flex min-w-0 flex-col">
            <span className="text-xs font-medium text-foreground">
              {m.name}
            </span>
            <span className="truncate text-xs text-muted-foreground">
              {m.text}
            </span>
          </div>
        </ListRow>
      ))}
    </div>
    <ActionButton>View all messages</ActionButton>
  </Panel>
);

const FILES = [
  { icon: FileText, name: "Project_Proposal.pdf", size: "2.4 MB" },
  { icon: FileType2, name: "Meeting_Notes.docx", size: "128 KB" },
  { icon: FileSpreadsheet, name: "Financial_Report.xlsx", size: "842 KB" },
];

const DocumentsPanel = () => (
  <Panel>
    <p className="text-xs font-medium text-muted-foreground">Recent files</p>
    <div className="flex flex-col">
      {FILES.map((f) => (
        <ListRow key={f.name}>
          <span className="flex size-7 shrink-0 items-center justify-center rounded-md bg-muted">
            <f.icon className="size-4 text-muted-foreground" />
          </span>
          <div className="flex min-w-0 flex-col">
            <span className="truncate text-xs font-medium text-foreground">
              {f.name}
            </span>
            <span className="text-muted-foreground text-[11px]">{f.size}</span>
          </div>
        </ListRow>
      ))}
    </div>
    <ActionButton>Manage documents</ActionButton>
  </Panel>
);

const WalletPanel = () => (
  <Panel>
    <div className="flex flex-col gap-0.5">
      <span className="text-xs text-muted-foreground">Current balance</span>
      <span className="text-2xl font-medium tracking-tight text-foreground">
        $1,250.32
      </span>
      <span className="flex items-center gap-1 text-xs text-emerald-600 dark:text-emerald-400">
        <TrendingUp className="size-3.5" />
        +12.4% this month
      </span>
    </div>
    <div className="border-t border-border" />
    <div className="flex flex-col gap-1 text-xs text-muted-foreground">
      <div className="flex justify-between">
        <span>Pending</span>
        <span className="font-medium text-foreground">$84.00</span>
      </div>
      <div className="flex justify-between">
        <span>Last payout</span>
        <span className="font-medium text-foreground">Sep 1</span>
      </div>
    </div>
    <ActionButton>View transactions</ActionButton>
  </Panel>
);

const ITEMS: ToolbarItem[] = [
  {
    id: 1,
    label: "User",
    icon: <User className="size-4.5" />,
    content: <UserPanel />,
  },
  {
    id: 2,
    label: "Messages",
    icon: <MessageCircle className="size-4.5" />,
    content: <MessagesPanel />,
  },
  {
    id: 3,
    label: "Documents",
    icon: <Folder className="size-4.5" />,
    content: <DocumentsPanel />,
  },
  {
    id: 4,
    label: "Wallet",
    icon: <WalletCards className="size-4.5" />,
    content: <WalletPanel />,
  },
];

export const ExpandableToolbarDemo = () => {
  return (
    <div className="relative flex h-80 w-full items-end justify-center pb-8">
      <ExpandableToolbar items={ITEMS} searchPlaceholder="Search notes" />
    </div>
  );
};

"use client";

import { cn } from "@/lib/utils";
import { AnimatePresence, motion, MotionConfig } from "motion/react";
import { ArrowLeft, Search } from "lucide-react";
import React, { useEffect, useRef, useState } from "react";

export type ToolbarItem = {
  id: number | string;
  /** Accessible name announced for the icon button. */
  label: string;
  /** Icon rendered inside the toolbar button. */
  icon: React.ReactNode;
  /** Panel content revealed when the item is active. */
  content: React.ReactNode;
};

export type ExpandableToolbarProps = {
  items: ToolbarItem[];
  /**
   * When set, a trailing search icon is appended to the bar. Clicking it
   * morphs the toolbar into a back arrow + search input.
   */
  searchPlaceholder?: string;
  /** Controlled search value (uncontrolled by default). */
  searchValue?: string;
  onSearchChange?: (value: string) => void;
  className?: string;
};

/**
 * A floating icon toolbar that springs open to reveal a panel of content
 * above the active icon. With `searchPlaceholder` set, a search icon morphs
 * the bar into a search input. Clicks outside collapse everything.
 */
export const ExpandableToolbar: React.FC<ExpandableToolbarProps> = ({
  items,
  searchPlaceholder,
  searchValue,
  onSearchChange,
  className,
}) => {
  const [active, setActive] = useState<ToolbarItem["id"] | null>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [isSearch, setIsSearch] = useState(false);
  const [query, setQuery] = useState("");
  const [panelHeight, setPanelHeight] = useState<number>(0);
  const rootRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const node = panelRef.current;
    if (!node) return;
    const measure = () => setPanelHeight(node.scrollHeight);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(node);
    return () => ro.disconnect();
  }, [active]);

  const closeAll = () => {
    setIsOpen(false);
    setActive(null);
    setIsSearch(false);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(event.target as Node)) {
        closeAll();
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleQueryChange = (next: string) => {
    onSearchChange?.(next);
    if (onSearchChange === undefined) setQuery(next);
  };

  return (
    <MotionConfig transition={{ type: "spring", bounce: 0.1, duration: 0.25 }}>
      <div ref={rootRef} className={cn("w-fit", className)}>
        <motion.div
          layout
          className="h-full w-fit rounded-xl bg-background smooth-shadow-ring-lg"
        >
          <div className="overflow-hidden">
            <AnimatePresence initial={false} mode="sync">
              {isOpen && !isSearch ? (
                <motion.div
                  key="toolbar-content"
                  initial={{ height: 0 }}
                  animate={{ height: panelHeight || "auto" }}
                  exit={{ height: 0 }}
                >
                  <div ref={panelRef} className="p-2">
                    {items.map((item) => {
                      const isSelected = active === item.id;
                      return (
                        <motion.div
                          key={item.id}
                          initial={{ opacity: 0 }}
                          animate={{ opacity: isSelected ? 1 : 0 }}
                          exit={{ opacity: 0 }}
                        >
                          <div
                            className={cn(
                              "px-2 pt-2 text-sm",
                              isSelected ? "block" : "hidden",
                            )}
                          >
                            {item.content}
                          </div>
                        </motion.div>
                      );
                    })}
                  </div>
                </motion.div>
              ) : null}
            </AnimatePresence>
          </div>

          {isSearch ? (
            <div className="flex w-72 gap-2 p-2">
              <button
                type="button"
                aria-label="Back"
                onClick={() => setIsSearch(false)}
                className="flex size-9 shrink-0 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground active:scale-[0.98]"
              >
                <ArrowLeft className="size-4.5" />
              </button>
              <input
                autoFocus
                placeholder={searchPlaceholder}
                value={searchValue ?? query}
                onChange={(e) => handleQueryChange(e.target.value)}
                className="h-9 w-full rounded-lg bg-muted px-3 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none"
              />
            </div>
          ) : (
            <div className="flex w-fit gap-2 p-2">
              {items.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  aria-label={item.label}
                  aria-expanded={isOpen && active === item.id}
                  onClick={() => {
                    if (active === item.id && isOpen) {
                      setIsOpen(false);
                      setActive(null);
                      return;
                    }
                    setIsOpen(true);
                    setActive(item.id);
                  }}
                  className={cn(
                    "relative flex size-9 shrink-0 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground active:scale-[0.98]",
                    active === item.id && "bg-accent text-foreground",
                  )}
                >
                  {item.icon}
                </button>
              ))}
              {searchPlaceholder !== undefined && (
                <button
                  type="button"
                  aria-label="Search"
                  onClick={() => {
                    setIsOpen(false);
                    setActive(null);
                    setIsSearch(true);
                  }}
                  className="relative flex size-9 shrink-0 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground active:scale-[0.98]"
                >
                  <Search className="size-4.5" />
                </button>
              )}
            </div>
          )}
        </motion.div>
      </div>
    </MotionConfig>
  );
};
